    WebCommand c;
    c.id       = ticket;
    c.cmd      = cmd;
    c.tag      = tag;
    c.hasTag   = !tag.empty();
    c.value    = value;
    c.hasValue = !value.isNull();  c.connId = connId;   // AI(W906-CONNID) 20260926: 以前從沒設 ⇒ wb_serve 收到的每個指令 connId 都是 0，ui.windows.put 把每個分頁都登記成同一條連線、互相蓋掉（St01 18:35 報）
    return q->tryPush(c);
